import {cleanConfig,readHistory,recordResult,summarizeHistory,readPresets,savePreset,deletePreset,clearHistory} from './guest-data.js';
const app=document.querySelector('#app');
const base=location.origin;
const STATIC_SITE=location.hostname.endsWith('.github.io');
let localEngine=null;
const COLOR=['red','blue','green','brown'];
const SYM={sun:'☀',moon:'☾',key:'⚿',glyph:'✧',tower:'♜',lostDream:'✿',nightmare:'✦',door:'◈',hidden:'◈',deadEnd:'⊘',happyDream:'✺',denizen:'♧',sphinx:'◇',diver:'▽',confusion:'≋'};
const EXP=[['Book of Steps','P4','book'],['Glyphs','P4','glyphs'],['Dreamcatchers','P4','dreamcatchers'],['Towers','P4','towers'],['Happy Dreams / Premonitions','P5','premonitions'],['Crossroads / Dead Ends','P5','crossroads'],['Door to the Oniverse','P5','oniverse'],['Mirrors (promo)','P6','mirrors'],['Sphinx / Diver / Confusion','P6','sphinx'],['Little Incubus','P6','incubus']];
let mirrorSelection=new Set();
let session=JSON.parse(localStorage.getItem('onirama.session')||'null');
let selectedExpansions=new Set(),selectedDifficulties={},spellSelected=new Set(),spellChoice='parallel',effectOrder=[],effectPick=null,effectDiscards=new Set();
const THEME_PRESETS=[{id:'ocean-light',name:'Ocean · Light',theme:'ocean',mode:'light'},{id:'ocean-dark',name:'Ocean · Dark',theme:'ocean',mode:'dark'},{id:'light',name:'Light',theme:'bw',mode:'light'},{id:'dark',name:'Dark',theme:'bw',mode:'dark'},{id:'forest',name:'Forest',theme:'forest',mode:'light'},{id:'forest-dark',name:'Forest · Dark',theme:'forest',mode:'dark'},{id:'clay',name:'Clay',theme:'clay',mode:'light'},{id:'clay-dark',name:'Clay · Dark',theme:'clay',mode:'dark'},{id:'berry',name:'Berry',theme:'berry',mode:'light'},{id:'berry-dark',name:'Berry · Dark',theme:'berry',mode:'dark'}];
const SETTINGS_KEY='onirama.ui.settings.v1';
const SESSION_META_KEY='onirama.guest.current.v1';
let tutorialStep=0,lastAnnouncement='';
function readSettings(){try{const raw=JSON.parse(localStorage.getItem(SETTINGS_KEY)||'{}');return {theme:THEME_PRESETS.some(p=>p.id===raw.theme)?raw.theme:'ocean-light',motion:raw.motion==='reduced'?'reduced':'normal',cardSize:raw.cardSize==='large'?'large':'normal',contrast:raw.contrast==='high'?'high':'normal',textSize:raw.textSize==='large'?'large':'normal'};}catch{return {theme:'ocean-light',motion:'normal',cardSize:'normal',contrast:'normal',textSize:'normal'};}}
let uiSettings=readSettings();
function applySettings(){const preset=THEME_PRESETS.find(p=>p.id===uiSettings.theme)||THEME_PRESETS[0];Object.assign(document.documentElement.dataset,{theme:preset.theme,mode:preset.mode,motion:uiSettings.motion,cardSize:uiSettings.cardSize,contrast:uiSettings.contrast,textSize:uiSettings.textSize});}
applySettings();
let state=null,selected=null,error='',busy=false,online=false,streamAbort=null,version=0,selectedMode='solo',page=location.hash||'#/';
const newId=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`;
function sessionMeta(){if(!session)return null;try{const meta=JSON.parse(localStorage.getItem(SESSION_META_KEY)||'null');if(meta?.roomId===session.id&&typeof meta.gameId==='string')return meta;}catch{}const meta={roomId:session.id,gameId:newId(),startedAt:Date.now()};localStorage.setItem(SESSION_META_KEY,JSON.stringify(meta));return meta;}
function beginGuestSession(){if(!session)return;localStorage.setItem(SESSION_META_KEY,JSON.stringify({roomId:session.id,gameId:newId(),startedAt:Date.now()}));}
function recordCurrentResult(){if(!state?.game||!['won','lost'].includes(state.game.status))return;try{const meta=sessionMeta();recordResult(localStorage,{id:meta.gameId,mode:state.game.mode,status:state.game.status,turn:state.game.turn,config:state.game.config,startedAt:meta.startedAt});}catch(e){console.warn('Unable to save guest result',e);}}
function announceCurrent(){const g=state?.game;if(!g)return;const key=`${g.status}:${g.phase}:${g.turn}:${g.active}:${g.pending?.type||''}`;if(key===lastAnnouncement)return;lastAnnouncement=key;const el=document.querySelector('#sr-announcer');if(el)el.textContent=g.status==='won'?'Game won. All objectives met.':g.status==='lost'?'Game lost.':g.phase==='decision'?'An effect needs a decision.':`Turn ${g.turn}: ${g.players[g.active]?.name||'Player'} to act.`;}
function currentSetup(){return cleanConfig({expansions:[...selectedExpansions],difficulties:Object.fromEntries(Object.entries(selectedDifficulties).filter(([id,v])=>selectedExpansions.has(id)&&v!=='normal'))});}

const escape=(x)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count=(arr)=>Array.isArray(arr)?arr.length:0;
const btn=(label,action,klass='')=>`<button type="button" class="${klass}" data-action="${action}">${label}</button>`;
const card=(c,{select=false,tiny=false,dim=false}={})=>{
  const symbol=c.kind==='location'?SYM[c.symbol]:(SYM[c.kind]||'◈');
  const text=c.kind==='location'?`${c.color==='wild'?'Crossroad':c.color} ${c.symbol}`:c.kind==='tower'?`${c.color} Tower · ${c.number} · ${c.left}/${c.right}`:c.kind==='door'?(c.expansion==='oniverse'?'Door to the Oniverse':`${c.color} Door`):c.kind==='hidden'?'Hidden':c.kind==='denizen'?`Denizen: ${c.ability}`:c.kind==='deadEnd'?'Dead End':c.kind==='happyDream'?'Happy Dream':c.kind;
  const classes=`card ${c.color||c.kind}${tiny?' tiny':''}${selected===c.id?' selected':''}`;
  return select?`<button class="${classes}" aria-pressed="${selected===c.id}" title="${escape(text)}" aria-label="${escape(text)}" data-pick="${escape(c.id)}" ${dim?'disabled':''}><span class="symbol">${symbol}</span><span class="card-label">${escape(text)}</span></button>`:`<div class="${classes}" title="${escape(text)}" aria-label="${escape(text)}"><span class="symbol">${symbol}</span><span class="card-label">${escape(text)}</span></div>`;
};
function nav(){return `<header class="nav"><a class="brand" href="#/">ONIRAMA</a><div class="nav-right"><a href="#/rules">Rules</a><a href="#/roadmap">Roadmap</a><a href="#/settings" aria-label="Settings">⚙</a></div></header>`;}
function bottomNav(){if(page==='#/game')return '';const entries=[['#/','Single Player','◈'],['#/multiplayer','Multiplayer','♧'],['#/settings','Settings','⚙']];const active=page==='#/multiplayer'||page==='#/join'?'#/multiplayer':(page==='#/settings'||page==='#/history'||page==='#/roadmap')?'#/settings':'#/';return `<nav class="bottom-nav" aria-label="Primary">${entries.map(([url,label,icon])=>`<a href="${url}" class="bottom-nav-item${active===url?' active':''}" ${active===url?'aria-current="page"':''}><span aria-hidden="true" class="bottom-icon">${icon}</span><span>${label}</span></a>`).join('')}</nav>`;}
function setRoute(path){location.hash=path;page=path;render();}
function setError(msg){error=msg;render();}
async function api(route,method='GET',body=null){
  const headers={'Content-Type':'application/json'};if(session?.token)headers.Authorization=`Bearer ${session.token}`;
  if(STATIC_SITE)throw Error('Online multiplayer requires the separately hosted Onirama server. Solo play is available here.');
  const res=await fetch(`${base}${route}`,{method,headers,body:body?JSON.stringify(body):undefined});const data=await res.json();
  if(!res.ok)throw Error(data.error||'Request failed');return data;
}
async function refresh(){if(STATIC_SITE){const raw=localStorage.getItem('onirama.solo.v1');if(raw&&localEngine){const game=JSON.parse(raw);state={room:{seat:0,mode:'solo',started:true},game:localEngine.viewFor(game,0),version:(version||0)+1};session={id:'local',seat:0};online=true;sessionMeta();recordCurrentResult();render();announceCurrent();}return;}if(!session)return;try{const data=await api(`/api/rooms/${session.id}/state`);state=data;version=data.version;error='';recordCurrentResult();render();announceCurrent();}catch(e){setError(e.message);}}
function saveSession(o){session={id:o.room.id,token:o.token,seat:o.room.seat};localStorage.setItem('onirama.session',JSON.stringify(session));}
async function create(mode){
  const name=(document.querySelector('#name')?.value||'Dreamwalker').trim();const config={ruleset:'official',expansions:[...selectedExpansions],difficulties:Object.fromEntries(Object.entries(selectedDifficulties).filter(([id,value])=>selectedExpansions.has(id)&&value!=='normal'))};busy=true;render();
  try{if(STATIC_SITE){if(mode==='coop')throw Error('Multiplayer requires the separately hosted game server; the GitHub Pages version supports solo.');localEngine??=await import('./engine/game.js');const game=localEngine.newGame({mode:'solo',config});localStorage.setItem('onirama.solo.v1',JSON.stringify(game));session={id:'local',seat:0};localStorage.setItem('onirama.session',JSON.stringify(session));beginGuestSession();await refresh();setRoute('#/game');return;}const o=await api(mode==='solo'?'/api/solo':'/api/rooms','POST',{name,config});saveSession(o);beginGuestSession();await refresh();setRoute('#/game');startStream();}
  catch(e){setError(e.message);}finally{busy=false;render();}
}
async function join(){const code=document.querySelector('#roomcode')?.value;const name=(document.querySelector('#joinname')?.value||'Partner').trim();
  if(STATIC_SITE)return setError('GitHub Pages hosts solo play. Multiplayer needs the separately hosted game server.');
  if(!code)return setError('Enter the six-to-eight-character room code.');
  try{const o=await api('/api/join','POST',{code,name});saveSession(o);await refresh();setRoute('#/game');startStream();}catch(e){setError(e.message);}
}
async function doRoom(operation,body={}){if(busy)return;busy=true;try{await api(`/api/rooms/${session.id}/${operation}`,'POST',body);await refresh();}catch(e){setError(e.message);}finally{busy=false;render();}}
async function action(command){if(busy)return;busy=true;render();try{if(STATIC_SITE){localEngine??=await import('./engine/game.js');const original=JSON.parse(localStorage.getItem('onirama.solo.v1'));const updated=localEngine.act(original,command);localEngine.assertConserved(updated);localStorage.setItem('onirama.solo.v1',JSON.stringify(updated));selected=null;effectOrder=[];effectPick=null;effectDiscards.clear();await refresh();return;}await api(`/api/rooms/${session.id}/action`,'POST',{expectedVersion:version,command});selected=null;spellSelected.clear();effectOrder=[];effectPick=null;effectDiscards.clear();await refresh();}catch(e){setError(e.message);await refresh();}finally{busy=false;render();}}
async function startStream(){
  if(STATIC_SITE){online=true;render();return;}
  streamAbort?.abort();if(!session)return;const controller=new AbortController();streamAbort=controller;online=false;render();
  try{
    const response=await fetch(`/api/rooms/${session.id}/stream`,{headers:{Authorization:`Bearer ${session.token}`},signal:controller.signal});
    if(!response.ok)throw Error('Disconnected');const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';online=true;render();
    while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const chunks=buffer.split('\n\n');buffer=chunks.pop()||'';
      for(const chunk of chunks){const line=chunk.split('\n').find(l=>l.startsWith('data: '));if(!line)continue;try{
        const incoming=JSON.parse(line.slice(6));state={...state,...incoming};
        // Version is refreshed after every notification to prevent stale submissions.
        const fresh=await api(`/api/rooms/${session.id}/state`);state=fresh;version=fresh.version;recordCurrentResult();render();announceCurrent();
      }catch{}}
    }
  }catch(e){if(e.name!=='AbortError'){online=false;render();}}
  finally{if(!controller.signal.aborted){online=false;render();setTimeout(()=>{if(session?.id)startStream();},2500);}}
}
function home(){return `<div class="route home-screen stack"><div class="title-row"><h1>Single Player</h1><span class="chip">Base + 7 expansions</span></div><section class="panel stack"><div class="eyebrow">The doors are waiting</div><p>Find eight Doors before the dream runs out. One player, five cards, and an ever-changing Labyrinth.</p><label for="name">Your display name</label><input id="name" class="inline-input" maxlength="40" value="Dreamwalker" autocomplete="nickname"><div class="actions">${btn('Start solo game','soloStart','primary')}${session?btn('Resume current game','resume'):''}${btn('Learn to play','tutorial')}</div></section><section class="panel stack"><h2 class="section-title">Expansions</h2><div class="expansion-list">${EXP.map(([name,phase,id])=>`<div class="expansion-row"><span>${escape(name)}</span><span class="chip">${'Available'}</span></div>`).join('')}</div><p class="muted small">All seven standard expansions and both promos are available. The Little Incubus is a separate base-game-only modifier.</p>${btn('Choose expansions','setup','primary')}</section><section class="panel stack"><h2 class="section-title">Your dream record</h2><p class="muted small">${readHistory(localStorage).length} finished games saved on this browser only. No account or tracking.</p>${btn('History & statistics','history')}</section></div>`;}
function multiplayer(){return `<div class="route stack"><div class="title-row"><h1>Multiplayer</h1><span class="chip">2-player cooperative</span></div><section class="panel stack"><div class="eyebrow">Host a game</div><p>Start a private room and share the 8-character invite code. Each player has their own hand and Labyrinth; two cards are shared.</p><label for="name">Your display name</label><input id="name" class="inline-input" maxlength="40" value="Dreamwalker" autocomplete="nickname"><div class="actions">${btn('Create room','coopStart','primary')}${!STATIC_SITE&&session?btn('Resume current room','resume'):''}</div></section><section class="panel stack"><div class="eyebrow">Join with a code</div><label for="roomcode">Invitation code</label><input id="roomcode" class="inline-input" placeholder="A1B2C3D4" maxlength="8" autocomplete="off"><label for="joinname">Your display name</label><input id="joinname" class="inline-input" value="Partner" maxlength="40">${btn('Join room','join','primary')}</section></div>`;}
function settings(){return `<div class="route stack"><div class="title-row"><h1>Settings</h1><span class="chip">Stored on this device</span></div><section class="panel stack"><h2 class="section-title">Appearance</h2><label for="themeChoice">Theme</label><select class="inline-input" id="themeChoice" data-setting="theme">${THEME_PRESETS.map(t=>`<option value="${t.id}" ${uiSettings.theme===t.id?'selected':''}>${escape(t.name)}</option>`).join('')}</select><label for="motionChoice">Animations</label><select class="inline-input" id="motionChoice" data-setting="motion"><option value="normal" ${uiSettings.motion==='normal'?'selected':''}>Normal</option><option value="reduced" ${uiSettings.motion==='reduced'?'selected':''}>Reduced motion</option></select><label for="cardSizeChoice">Card size</label><select class="inline-input" id="cardSizeChoice" data-setting="cardSize"><option value="normal" ${uiSettings.cardSize==='normal'?'selected':''}>Standard</option><option value="large" ${uiSettings.cardSize==='large'?'selected':''}>Large</option></select><label for="contrastChoice">Contrast</label><select class="inline-input" id="contrastChoice" data-setting="contrast"><option value="normal" ${uiSettings.contrast==='normal'?'selected':''}>Standard</option><option value="high" ${uiSettings.contrast==='high'?'selected':''}>High contrast</option></select><label for="textSizeChoice">Text size</label><select class="inline-input" id="textSizeChoice" data-setting="textSize"><option value="normal" ${uiSettings.textSize==='normal'?'selected':''}>Standard</option><option value="large" ${uiSettings.textSize==='large'?'selected':''}>Large</option></select></section><section class="panel stack"><h2 class="section-title">Gameplay and privacy</h2><p class="muted small">No login required. The current room is saved in this browser; game sessions are stored by the game server. Accounts are not part of Onirama. Guest sessions, settings, and room codes work without registration.</p><div class="actions">${session?btn('Resume current game','resume','primary'):''}${btn('How to play','rules')}${btn('Guided tutorial','tutorial')}${btn('History & statistics','history')}${btn('Development roadmap','roadmap')}</div></section></div>`;}
function setup(){return `<div class="route"><div class="title-row"><h1>New dream</h1><span class="chip">${76+12*Number(selectedExpansions.has('glyphs'))+4*Number(selectedExpansions.has('dreamcatchers'))+12*Number(selectedExpansions.has('towers'))+4*Number(selectedExpansions.has('premonitions'))+16*Number(selectedExpansions.has('crossroads'))+17*Number(selectedExpansions.has('oniverse'))+14*Number(selectedExpansions.has('sphinx'))} draw cards</span></div><div class="panel stack"><div class="eyebrow">Choose your mode</div><div class="grid"><button class="${selectedMode==='solo'?'primary':''}" data-action="chooseSolo">◈ Solo</button><button class="${selectedMode==='coop'?'primary':''}" data-action="chooseCoop">◈ Two-player cooperative</button></div><label for="name" class="small">Your display name</label><input class="inline-input" id="name" value="Dreamwalker" maxlength="40" autocomplete="nickname"><div class="eyebrow">Expansions</div><div class="stack">${EXP.map(([name,phase,id])=>`<label class="expansion-option"><input type="checkbox" data-expansion="${id||''}" ${selectedExpansions.has(id)?'checked':''} > <span>${escape(name)}</span> <span class="chip">Playable</span></label>${selectedExpansions.has(id)&&['book','dreamcatchers','towers','premonitions','crossroads','mirrors','incubus'].includes(id)?`<label class="muted small">${name} difficulty <select class="inline-input" data-difficulty="${id}">${id==='incubus'?`<option value="easy" ${!selectedDifficulties[id]||selectedDifficulties[id]==='easy'?'selected':''}>New Dreamwalker</option><option value="apprentice" ${selectedDifficulties[id]==='apprentice'?'selected':''}>Apprentice</option><option value="true" ${selectedDifficulties[id]==='true'?'selected':''}>True Dreamwalker</option>`:`<option value="normal" ${selectedDifficulties[id]!=='hard'?'selected':''}>Normal</option><option value="hard" ${selectedDifficulties[id]==='hard'?'selected':''}>Difficult</option>`}${id==='premonitions'?`<option value="extreme" ${selectedDifficulties[id]==='extreme'?'selected':''}>Very difficult (6)</option>`:''}</select></label>`:''}`).join('')}</div><p class="notice">Promotional expansions are playable. Little Incubus must be used alone (base game). Online multiplayer requires a separate server; this Pages edition provides offline solo.</p>${btn(`Start ${selectedMode==='solo'?'solo game':'cooperative room'}`,'create','primary')}</div><div class="panel stack"><h2 class="section-title">Saved setups · This device</h2><label for="presetName">Save current expansion choices as</label><input id="presetName" class="inline-input" maxlength="48" placeholder="e.g. Glyphs + Towers">${btn('Save setup','presetSave','primary')}<div class="stack">${readPresets(localStorage).map(p=>`<div class="preset-row"><strong>${escape(p.name)}</strong><span class="muted micro">${p.config.expansions.length} expansion(s)</span>${btn('Load',`presetLoad:${p.id}`,'mini')}${btn('Delete',`presetDelete:${p.id}`,'mini danger')}</div>`).join('')||'<span class="muted small">No saved setups yet.</span>'}</div></div></div>`;}
function joinPage(){return `<div class="route"><h1 class="section-title">Join a dream</h1><div class="panel stack"><label for="roomcode">Room code</label><input id="roomcode" class="inline-input" placeholder="A1B2C3D4" maxlength="8" autocomplete="off"><label for="joinname">Your display name</label><input id="joinname" class="inline-input" value="Partner" maxlength="40">${btn('Join room','join','primary')}</div></div>`;}
function lobby(room){return `<div class="route stack"><div class="title-row"><h1>Cooperative room</h1><span class="chip">Invite-only</span></div><div class="panel stack"><div class="eyebrow">Invite your partner</div><div class="code">${escape(room.code)}</div><p class="muted small">Share this code. Both players must join and mark themselves ready.</p><div class="grid"><div class="panel"><strong>Player 1 ${room.connected[0]?'✓':'—'}</strong><p class="muted small">${room.ready[0]?'Ready':'Not ready'}</p></div><div class="panel"><strong>Player 2 ${room.connected[1]?'✓':'—'}</strong><p class="muted small">${room.ready[1]?'Ready':'Waiting to join'}</p></div></div><div class="actions">${btn(room.ready[room.seat]?'Unready':'I’m ready','ready','primary')}${room.host?btn('Start cooperative game','start',room.ready.every(Boolean)&&room.connected[1]?'primary':''):''}${btn('Copy room code','copyCode')}</div><p class="muted small">Game starts with an eight-card public draft: three personal cards per player, two shared cards.</p></div></div>`;}
function doors(p){return `<div class="door-spots">${COLOR.map(color=>`<div class="door-group"><div class="eyebrow">${color}</div><div class="cards">${p.doors.filter(x=>x.color===color).map(x=>card(x,{tiny:true})).join('')||'<div class="door-slot">◇</div>'}</div></div>`).join('')}</div>`;}
function expansionBoard(g,canAct){const e=g.expansion||{},parts=[];
 if(e.book){const b=e.book;parts.push(`<section class="panel stack"><div class="section-label">Book of Steps · Goals</div><div class="goal-row">${b.goals.map((goal,i)=>`<span class="goal ${goal.color} ${goal.done?'done':''}" title="Goal ${i+1}">${i+1}. ${goal.color}${goal.done?' ✓':''}</span>`).join('')}</div><div class="muted small">Next required Door: ${b.goals.find(x=>!x.done)?.color||'Complete'} · ${b.discardCount} cards removed</div>${canAct&&g.status==='active'&&g.phase!=='draft'?`<div class="stack"><label>Spell <select id="spellChoice" class="inline-input" data-spell-choice="true"><option value="parallel" ${spellChoice==='parallel'?'selected':''}>Parallel Planning (${b.costs.parallel})</option><option value="paradox" ${spellChoice==='paradox'?'selected':''}>Paradoxical Prophecy (${b.costs.paradox})</option><option value="punishment" ${spellChoice==='punishment'?'selected':''}>Powerful Punishment (${b.costs.punishment})</option></select></label><div class="muted small">Choose exactly ${b.costs[spellChoice]} discarded cards as payment.</div><div class="cards">${g.discard.map(c=>`<button class="cost-option ${spellSelected.has(c.id)?'selected':''}" data-action="spellCost:${c.id}" title="${escape(c.color||c.kind)} ${escape(c.symbol||'')}" aria-pressed="${spellSelected.has(c.id)}">${escape(c.color||c.kind)} ${escape(c.symbol||'')}</button>`).join('')||'No cards in discard.'}</div>${spellChoice==='parallel'?`<div class="row">Swap Goal <input class="inline-input goal-input" id="goalA" type="number" min="1" max="${b.goals.length}" value="1"> with <input class="inline-input goal-input" id="goalB" type="number" min="1" max="${b.goals.length}" value="2"></div>`:''}${btn('Cast selected spell','castSpell','primary')}</div>`:''}</section>`);}
 if(e.premonitions)parts.push(`<section class="panel stack"><div class="section-label">Dark Premonitions · ${e.premonitions.reserveCount} unseen</div><div class="actions">${e.premonitions.faceUp.map(id=>`<span class="chip">${escape(id)}</span>`).join('')||'<span class="muted">All resolved</span>'}</div></section>`);
 if(e.oniverse)parts.push(`<section class="panel stack"><div class="section-label">Door to the Oniverse / Rallied Denizens</div><div class="cards">${e.oniverse.rallied.map(d=>`<div class="stack">${card(d,{tiny:true})}${canAct&&g.phase==='action'&&d.owner===g.active&&['architect','cyclobot','squirrel','harpoon','hammer','keeper'].includes(d.ability)?btn('Use',`denizen:${d.id}`,'mini'):''}</div>`).join('')||'<span class="muted small">No Denizens rallied.</span>'}</div>${e.oniverse.treasure.length?`<div class="section-label">Stored by Treasure Keeper</div><div class="cards">${e.oniverse.treasure.map(c=>card(c,{tiny:true,select:canAct&&g.phase==='action'})).join('')}</div>`:''}</section>`);
 if(e.crossroads)parts.push(`<div class="notice small">Crossroads are wild-colored Locations; Dead Ends cannot be played or discarded individually.${e.crossroads.hard?' Hard: Crossroads only in the middle of sequences.':''}</div>`);
 if(e.towers){const t=e.towers;parts.push(`<section class="panel"><div class="section-label">Tower Alignment ${t.protected?'· protected':''}</div><div class="cards">${t.alignment.map(c=>card(c,{tiny:true})).join('')||'<span class="muted small">Play Tower cards to either end. You need four adjacent colors.</span>'}</div></section>`);}
 if(e.dreamcatchers){const d=e.dreamcatchers;parts.push(`<section class="panel stack"><div class="section-label">Dreamcatchers · ${d.failsafes} Failsafe Books</div><div class="catcher-grid">${d.stacks.map((cards,i)=>`<div class="catcher-slot"><strong>${d.active[i]?`Catcher ${i+1}`:`Lost ${i+1}`}</strong><span class="muted micro">${cards.length} cards · ${cards.filter(c=>c.kind==='lostDream').length} Lost Dreams</span>${canAct&&g.phase==='action'&&d.active[i]&&cards.length&&d.failsafes?btn('Free (1 book)',`freeCatcher:${i}`,'mini'):''}</div>`).join('')}</div></section>`);}
 if(e.mirrors)parts.push(`<section class="panel stack"><div class="section-label">Mirrors</div><div class="mirror-grid">${Object.entries(e.mirrors.stacks).map(([name,cards])=>`<div class="catcher-slot"><strong>${escape(name)} ${e.mirrors.completed.includes(name)?'✓':'· '+cards.length+'/4'}</strong>${!e.mirrors.completed.includes(name)&&canAct&&g.phase==='action'?btn('Play two',`mirrorPlay:${name}`,'mini'):''}</div>`).join('')}</div></section>`);
 if(e.incubus)parts.push(`<section class="panel stack"><div class="section-label">Little Incubus · ${escape(e.incubus.level)}</div><p class="muted small">Stored Locations: ${e.incubus.stored.length}. ${e.incubus.used?'One-time cancellation spent.':''}</p>${canAct&&g.phase==='action'&&e.incubus.level!=='easy'&&!e.incubus.stored.length?btn('Anticipate Nightmare','incubusActivate','primary'):''}</section>`);
 if(g.config.expansions.includes('glyphs'))parts.push(`<div class="notice muted small">Glyphs: 12 Doors needed. Discard a Glyph to reveal five cards and claim one revealed Door.</div>`);
 return parts.join('');}
function effectReorder(p){if(!p.cards)return '';const ids=p.cards.map(c=>c.id);if(effectOrder.length!==ids.length||effectOrder.some(id=>!ids.includes(id)))effectOrder=[...ids];
 const modes={sphinxResolve:'Sphinx — choose the top card if your named aspect matched; arrange the others bottom-first.',diver:'Diver — stop and put last card on top, continue revealing, or resolve a Nightmare.',denizenPeek:'Denizen insight — reorder inspected cards.',happyPeek:'Happy Dream — choose zero or more cards to discard, then reorder the rest.',incantation:'Incantation — choose one Door (if available) and order the others from bottom to top.',towerLook:'Tower insight — order inspected cards from top to bottom.',spellPeek:'Paradoxical Prophecy — pick one card to put on top; order the others from bottom to top.'};
 const options=p.cards.filter(c=>p.type==='incantation'?c.kind==='door':['spellPeek','sphinxResolve'].includes(p.type));
 if(effectPick&&!options.some(c=>c.id===effectPick))effectPick=null;
 return `<section class="decision stack"><h2>${escape(modes[p.type])}</h2><p>Use arrows to rearrange the revealed cards. Leftmost is first in the indicated ordering.</p><div class="cards">${effectOrder.map(id=>{const c=p.cards.find(x=>x.id===id);return `<div class="stack" style="align-items:center">${card(c)}${options.some(x=>x.id===id)?btn(effectPick===id?'✓ Selected':'Select',`effectPick:${id}`,'mini'):''}${p.type==='happyPeek'?btn(effectDiscards.has(id)?'✓ Discard':'Keep / discard',`effectDiscard:${id}`,'mini'):''}${btn('↑',`effectUp:${id}`,'mini')}${btn('↓',`effectDown:${id}`,'mini')}</div>`;}).join('')}</div>${p.type==='sphinxResolve'?`<div class="actions">${p.cards.map(c=>btn(`Top: ${c.id}`,`effectPick:${c.id}`,'mini')).join('')}</div>${btn('Resolve Sphinx','sphinxConfirm','primary')}`:p.type==='diver'?`<div class="actions">${p.cards.at(-1)?.kind==='nightmare'?btn('Resolve Diver as Nightmare','diverNightmare','danger'):btn('Stop here','diverStop','primary')}${p.cards.at(-1)?.kind!=='nightmare'&&p.remaining!==0?btn('Reveal another','diverContinue'):''}</div>`:btn('Confirm effect','effectConfirm','primary')}</section>`;
}
function catcherSearchChoice(g,searchesDeck){
 if(!searchesDeck||!g.expansion?.dreamcatchers)return '';
 const d=g.expansion.dreamcatchers;
 return `<label class="muted small">Optional: free a Dreamcatcher when shuffling after this search<select id="freeOnSearch" class="inline-input"><option value="">Do not free</option>${d.stacks.map((stack,i)=>stack.length&&d.active[i]?`<option value="${i}">Free catcher ${i+1}</option>`:'').join('')}</select></label>`;
}
function searchFreeId(){const selected=document.querySelector('#freeOnSearch')?.value;return selected===undefined||selected===''?undefined:Number(selected);}
function decision(g,canAct){
  if(g.phase!=='decision')return '';
  if(!canAct)return `<div class="notice">Your partner is resolving a card effect.</div>`;
  const p=g.pending;if(!p)return '';
  if(p.type==='sphinxName')return `<section class="decision stack"><h2>Sphinx: name an aspect</h2><div class="actions">${[...COLOR,'moon','key',...(g.config.expansions.includes('glyphs')?['glyph']:[])].map(a=>btn(a,`sphinxName:${a}`,'primary')).join('')}</div></section>`;
  if(p.type==='sphinxResolve'||p.type==='diver')return effectReorder(p);
  if(p.type==='confusion')return `<section class="decision stack"><h2>Confusion</h2><p>Return your hand to the bottom of the deck in your chosen order, then redraw.</p>${btn('Choose order and resolve','confusionResolve','primary')}</section>`;
  if(p.type==='mirrorReward')return `<section class="decision stack"><h2>${escape(p.mirror)} Mirror reward</h2><p>Select cards from the ${p.mirror==='blue'?'discard pile':'deck'}; choose exactly the printed number if available.</p>${p.mirror==='key'?`<label>Door color <select id="mirrorColor" class="inline-input">${COLOR.map(c=>`<option>${c}</option>`).join('')}</select></label>`:''}<div class="stack">${p.options.map(c=>`<label class="cost-option"><input type="checkbox" data-mirror-choice="${c.id}" ${mirrorSelection.has(c.id)?'checked':''}> ${escape(c.color||'')} ${escape(c.symbol||c.kind)}</label>`).join('')}</div>${catcherSearchChoice(g,p.mirror!=='blue')}${btn('Apply Mirror effect','mirrorRewardConfirm','primary')}</section>`;
  if(p.type==='doorSearch')return `<section class="decision stack"><h2>A Door awaits</h2><p>Three ${p.color} Locations. Search for an eligible Door, or skip.</p><div class="actions">${(p.targets||[]).map(t=>btn(`Claim ${p.color} Door (${t.source==='deck'?'deck':`Catcher ${Number(t.source.slice(5))+1}`})`,`doorSearch:claim:${t.id}`,'primary')).join('')||btn('Claim Door','doorSearch:claim','primary')}${btn('Skip','doorSearch:skip')}</div>${g.expansion?.dreamcatchers?`<p class="muted small">Optional: free one Dreamcatcher when shuffling after a deck search.</p><select id="freeOnSearch" class="inline-input"><option value="">Do not free</option>${g.expansion.dreamcatchers.stacks.map((stack,i)=>stack.length&&g.expansion.dreamcatchers.active[i]?`<option value="${i}">Free catcher ${i+1}</option>`:'').join('')}</select>`:''}</section>`;
  if(p.type==='door')return `<section class="decision stack"><h2>Oneiric Door</h2><p>A ${p.card.color} Door appeared. Spend a matching Key to claim it, or put the Door into Limbo.</p><div class="actions">${p.keys.map(k=>btn(`Use ${k.zone} Key` ,`useKey:${k.id}`,'primary')).join('')}${btn('Send to Limbo','useKey:limbo')}</div></section>`;
  if(p.type==='nightmare'){
    const keys=[...g.players[g.active].hand,...(g.mode==='coop'?g.shared:[])].filter(c=>c.symbol==='key');
    const ds=g.players[g.active].doors;
    return `<section class="decision stack"><h2>A Nightmare</h2><p>Choose one of the four official penalties. Unavailable resources cannot be sacrificed.</p><div class="stack">${g.expansion?.incubus&&!p.incubus&&(g.expansion.incubus.level==='easy'?!g.expansion.incubus.used:g.expansion.incubus.stored.length>0)?btn('Cancel with Little Incubus','incubusCancel','primary'):''}${(g.expansion?.oniverse?.rallied||[]).filter(d=>d.ability==='mirror'&&d.owner===g.active).map(d=>btn('Mirror Denizen — cancel Nightmare',`mirror:${d.id}`,'primary')).join('')}${keys.length?`<div class="small">Discard a Key: <div class="actions">${keys.map(k=>btn(`${k.color} Key`,`nightKey:${k.id}`)).join('')}</div></div>`:''}${ds.length?`<div class="small">Lose a Door: <div class="actions">${ds.map(d=>btn(`${d.color} Door`,`nightDoor:${d.id}`)).join('')}</div></div>`:''}<div class="actions">${btn('Reveal up to 5 cards','nightReveal')}${btn('Discard and replace entire hand','nightHand','danger')}</div></div></section>`;
  }
  if(p.type==='prophecy')return prophecy(g);
  if(p.type==='happyDream')return `<section class="decision stack"><h2>Happy Dream</h2><p>Choose one benefit.</p><div class="actions">${(g.expansion?.premonitions?.faceUp||[]).map(id=>btn(`Cancel ${id}`,`happyBanish:${id}`,'primary')).join('')}${btn('Inspect top seven','happyPeek','primary')}${btn('Search for one card','happyFetch','primary')}</div></section>`;
  if(p.type==='happyFetch')return `<section class="decision stack"><h2>Happy Dream — find a card</h2><p>Select one deck card to place on top (deck reshuffles).</p><div class="actions">${p.options.map(c=>btn(`${c.color||c.ability||c.kind} ${c.symbol||c.kind}`,`happyFetch:${c.id}`,'mini')).join('')}</div>${catcherSearchChoice(g,true)}</section>`;
  if(p.type==='rally')return `<section class="decision stack"><h2>Rally ${escape(p.card.ability)}?</h2><p>Discard an eligible Location to keep this Denizen for one later ability.</p><div class="actions">${p.choices.map(id=>btn(`Discard ${id} and rally`,`rally:${id}`,'primary')).join('')}${btn('Do not rally','rally:skip')}</div></section>`;
  if(p.type==='premonitionPick')return `<section class="decision stack"><h2>Dark Premonitions triggered</h2><p>Choose the order of resolving the active conditions.</p><div class="actions">${p.options.map(id=>btn(`Resolve ${id}`,`premonitionPick:${id}`,'danger')).join('')}</div></section>`;
  if(p.type==='premonitionDoor')return `<section class="decision stack"><h2>Premonition — sacrifice a Door</h2><div class="actions">${p.choices.map(d=>btn(`Lose ${d.color} Door · Player ${d.owner+1}`,`premonitionDoor:${d.id}`,'danger')).join('')}</div></section>`;
  if(['incantation','towerLook','spellPeek','happyPeek','denizenPeek'].includes(p.type))return effectReorder(p);
  if(p.type==='catchChoose'||p.type==='catchOverload')return `<section class="decision stack"><h2>${p.type==='catchChoose'?'Assign Limbo to a free Dreamcatcher':'Dreamcatcher overload'}</h2><p>${p.type==='catchChoose'?'Choose which free Dreamcatcher stores this turn’s Limbo.':'All catchers are occupied. Sacrifice one catcher and shuffle its cards with Limbo.'}</p><div class="actions">${p.choices.map(i=>btn(`Catcher ${i+1}`,`${p.type}:${i}`,'primary')).join('')}</div></section>`;
  if(p.type==='towerPenalty')return `<section class="decision stack"><h2>Nightmare threatens the Towers</h2><p>Discard a legal Tower, or put this Nightmare into Limbo instead (false destruction).</p><div class="actions">${g.expansion.towers.alignment.map(t=>btn(`Discard ${t.color} Tower`,`towerPenalty:${t.id}`)).join('')}${btn('False destruction','towerFake','primary')}</div></section>`;
  return `<div class="notice">Resolving an effect.</div>`;
}
let prophecyDiscard=null,prophecyOrder=[];
function prophecy(g){const cards=g.pending.cards;if(!cards)return '';
  if(!cards.some(c=>c.id===prophecyDiscard)){prophecyDiscard=null;prophecyOrder=cards.map(c=>c.id);}
  if(prophecyOrder.length!==cards.length||prophecyOrder.some(id=>!cards.some(c=>c.id===id)))prophecyOrder=cards.map(c=>c.id);
  return `<section class="decision stack"><h2>Prophecy</h2><p>Choose exactly one card to discard. Reorder the others from top to bottom, then confirm.</p><div class="cards">${prophecyOrder.map((id,index)=>{const c=cards.find(x=>x.id===id);return `<div class="stack" style="align-items:center">${card(c,{tiny:false})}${btn(prophecyDiscard===id?'✓ Discard':'Discard',`prophecyDiscard:${id}`,'mini')}${btn('↑',`prophecyUp:${id}`,'mini')}${btn('↓',`prophecyDown:${id}`,'mini')}</div>`;}).join('')}</div><div class="muted small">Leftmost card will be drawn first.</div>${btn('Confirm Prophecy','prophecyConfirm',prophecyDiscard?'primary':'')}</section>`;
}
function board(g,room){
  const canAct=room.seat===g.active,player=g.players[g.active],my=g.players[room.seat],isDraft=g.phase==='draft';
  let help=g.status==='won'?'Victory — all objectives completed!':g.status==='lost'?'Defeat — the deck was exhausted.':isDraft?'Select a Location from the public draft.':canAct?'Choose one of your available Locations to play or discard.':`Waiting for ${escape(player.name)}.`;
  const mine=g.mode==='solo'?player:my;
  const selections=[...mine.hand,...(g.mode==='coop'?g.shared:[]),...(g.expansion?.oniverse?.treasure||[])];const chosen=selections.find(c=>c.id===selected);
  return `<div class="title-row"><h1>${g.mode==='solo'?'Solo labyrinth':'Cooperative labyrinth'}</h1><div class="status"><span class="dot ${online?'':'off'}"></span> ${online?'Connected':'Connecting'} · Turn ${g.turn} · ${g.deckCount} in deck</div></div><div class="game-layout"><section class="board-main"><div class="notice">${help}</div>${g.config.expansions.includes('towers')?'<div class="notice">Towers: printed edge symbols are provisional while the physical-card audit is pending.</div>':''}${g.status!=='active'?`<div class="panel"><h2 class="section-title">${g.status==='won'?'Dream escaped':'The dream ends'}</h2><p>${escape(g.log.at(-1)||'')}</p>${btn('New game','setup','primary')} ${btn('View history','history')}</div>`:''}
  ${isDraft?`<div class="panel"><div class="section-label">Public draft · ${escape(player.name)} chooses</div><div class="cards">${g.draft.map(c=>card(c,{select:canAct})).join('')}</div><p class="muted small">Each player chooses three cards, alternating turns. The remaining two become shared resources.</p></div>`:''}
  <div class="panel"><div class="row"><div class="section-label">Collected Doors</div><span class="chip">${g.players.reduce((n,p)=>n+p.doors.length,0)}/${(g.config.expansions.includes('glyphs')?12:8)+Number(g.config.expansions.includes('oniverse'))}</span></div>${g.players.map(p=>`<div class="stack"><strong class="small">${escape(p.name)}</strong>${doors(p)}</div>`).join('')}</div>
  <div class="panel"><div class="section-label">${escape(player.name)}’s Labyrinth</div><div class="cards">${player.labyrinth.slice(-18).map(c=>card(c,{tiny:true})).join('')||'<span class="muted small">No Locations played yet</span>'}</div><p class="muted micro">The last card controls which symbol can be played next. Three consecutive matching colors unlock a Door.</p></div>
  ${g.mode==='coop'?`<div class="panel"><div class="section-label">Partner Labyrinth</div><div class="cards">${g.players[1-g.active].labyrinth.slice(-18).map(c=>card(c,{tiny:true})).join('')||'<span class="muted small">Empty</span>'}</div></div>`:''}
  ${expansionBoard(g,canAct)}${decision(g,canAct)}
  <div class="panel"><div class="row"><div class="section-label">Your personal cards</div><span class="muted micro">${count(mine.hand)} cards</span></div><div class="cards">${mine.hand.map(c=>card(c,{select:canAct&&g.phase==='action'&&c.kind!=='deadEnd'})).join('')}</div>${g.mode==='coop'?`<div class="section-label" style="margin-top:24px">Shared resources</div><div class="cards">${g.shared.map(c=>card(c,{select:canAct&&g.phase==='action'&&c.kind!=='deadEnd'})).join('')}</div>`:''}${canAct&&g.phase==='action'?`<div class="actions spaced">${g.config.expansions.includes('crossroads')?btn('Escape — redraw full hand','escape','mini'):''}${chosen?.kind==='tower'?btn('Play Tower left','towerLeft','primary')+btn('Play Tower right','towerRight','primary'):btn('Play selected','play',chosen&&chosen.symbol!==player.labyrinth.at(-1)?.symbol?'primary':'')}${chosen?.kind!=='deadEnd'?btn('Discard selected','discard',chosen?'':'ghost'):''}${g.mode==='coop'?'<span class="muted micro">Optional swap available after discarding</span>':''}</div>`:''}</div></section>
  <aside class="board-side"><div class="panel"><div class="section-label">Dream status</div><div class="stack"><div class="row"><span>Draw pile</span><strong>${g.deckCount}</strong></div><div class="row"><span>Discard</span><strong>${g.discard.length}</strong></div><div class="row"><span>Limbo</span><strong>${g.limbo.length}</strong></div><div class="row"><span>Turn owner</span><strong>${escape(player.name)}</strong></div></div></div><div class="panel"><div class="section-label">Discard pile</div><div class="cards">${g.discard.slice(-5).map(c=>card(c,{tiny:true})).join('')||'<span class="muted small">Empty</span>'}</div></div><div class="panel"><div class="section-label">Action history</div><div class="log">${g.log.slice(-35).reverse().map(msg=>`<div>${escape(msg)}</div>`).join('')}</div></div><div class="panel"><div class="section-label">Rules</div><p class="muted small">Active: ${g.config.expansions.length?g.config.expansions.map(id=>EXP.find(e=>e[2]===id)?.[0]||id).join(', '):'Base game'}.</p>${btn('View rules','rules','mini')}</div></aside></div>`;
}
function rules(){return `<article class="route panel prose"><div class="eyebrow">How to play</div><h1 class="section-title">The base game</h1><p>Find all eight Doors before the deck runs out. Solo players collect two Doors of each of four colors. In cooperative play, each player must collect one Door of each color.</p><h2>Each turn</h2><ol><li><strong>Play or discard</strong> one Location. Played Locations must not have the same symbol as the previous Labyrinth card. The third consecutive played Location of a color unlocks one matching Door from the deck; the fourth starts a new sequence.</li><li><strong>Refill</strong> your personal resources to five (or three personal plus two shared in cooperative play). Doors drawn can be claimed with a matching Key from your resources; otherwise they enter Limbo. Nightmares must be resolved immediately.</li><li><strong>Shuffle Limbo</strong> back into the deck at the end of the turn.</li></ol><h2>Keys and Prophecy</h2><p>Discarding a Key lets you inspect the top five cards, discard exactly one, and rearrange the remaining cards on top of the deck.</p><h2>Nightmare penalties</h2><ol><li>Discard a Key.</li><li>Return an acquired Door to Limbo.</li><li>Reveal up to five cards, discarding Locations and placing Dreams/Doors in Limbo.</li><li>Discard and rebuild the entire hand, setting aside Dreams and Doors without resolving them.</li></ol><h2>Cooperative play</h2><p>After revealing eight Locations, players alternately draft three personal cards each; the last two become shared resources. You may play or discard a card from your personal or shared resources on your own turn. You can swap one personal card with one shared card after discarding. Each player has their own Labyrinth and Doors.</p><h2>References</h2><p><a href="https://www.rulespal.com/onirim/rulebook" target="_blank" rel="noopener noreferrer">Onirim Second Edition rules</a></p><p class="notice">This is an original visual implementation and is not affiliated with the game's publisher. Standard expansion support is under development.</p></article>`;}
function roadmap(){const items=[['0','Repository & CI','Implemented'],['1','Base solo engine & interface','Implemented'],['2','Two-player cooperative rooms','Implemented foundation'],['3','Expansion framework and three-tab UI','Implemented foundation'],['4','Book of Steps, Glyphs, Dreamcatchers, Towers','Implemented'],['5','Premonitions, Crossroads, Oniverse Door','Implemented'],['6','Promo sets, Little Incubus & variants','Implemented'],['7','Cross-expansion regression audit','Implemented (remaining rulings documented)'],['8','Guest history, statistics, tutorials, accessibility','Implemented'],['9','Production release and security hardening','Planned']];return `<div class="route"><div class="title-row"><h1>Development phases</h1><span class="chip">Living plan</span></div><div class="stack">${items.map(([num,name,status])=>`<div class="panel row"><div><span class="eyebrow">Phase ${num}</span><h2 style="margin:5px 0;font-size:1.1rem">${escape(name)}</h2></div><span class="chip">${escape(status)}</span></div>`).join('')}</div></div>`;}
const TUTORIAL=[
  ['The objective','Collect all eight Doors before the draw deck is exhausted. Each color has two Doors in solo play.'],
  ['Your hand','Begin with five Location cards. On each turn, play one Location into your Labyrinth or discard one.'],
  ['Symbol restriction','The next played Location must have a different symbol (Sun, Moon or Key) from the last played card. The colors may be the same.'],
  ['Open Doors','Three consecutive played Locations of one color let you search the deck for a matching Door. The next card begins a new sequence.'],
  ['Keys and Prophecy','Discarding a Key activates Prophecy: look at five cards, discard one, and rearrange the remaining cards on top.'],
  ['Doors and Nightmares','While refilling, a drawn Door can be claimed with a matching Key. For a Nightmare, choose a permitted penalty; the game handles Limbo afterward.'],
  ['Expand the dream','Turn on expansions in New Dream; special objectives and decisions appear on the board. Start with the base game if learning.']
];
function tutorial(){const [heading,body]=TUTORIAL[tutorialStep];return `<div class="route stack"><div class="title-row"><h1>Guided tutorial</h1><span class="chip">${tutorialStep+1} / ${TUTORIAL.length}</span></div><section class="panel stack"><div class="eyebrow">Learning Onirama</div><h2 class="section-title">${heading}</h2><p>${body}</p><div class="tutorial-track"><div style="width:${(tutorialStep+1)/TUTORIAL.length*100}%"></div></div><div class="actions">${tutorialStep>0?btn('Back','tutorialBack'):''}${tutorialStep<TUTORIAL.length-1?btn('Next','tutorialNext','primary'):btn('Start base game','tutorialStart','primary')}${btn('Full rules','rules')}</div></section></div>`;}
function historyPage(){const list=readHistory(localStorage),stats=summarizeHistory(list);return `<div class="route stack"><div class="title-row"><h1>History & statistics</h1><span class="chip">This browser only</span></div><div class="stats-grid">${[['Games',stats.played],['Victories',stats.wins],['Win rate',stats.winRate+'%'],['Solo / Coop',stats.solo+' / '+stats.coop]].map(([label,value])=>`<div class="panel stat-box"><div class="muted small">${label}</div><strong>${value}</strong></div>`).join('')}</div><section class="panel stack"><h2 class="section-title">Completed games</h2><p class="muted small">Only final summaries are stored locally; no card hands, room credentials, or replay data. Clearing browser data erases these records.</p>${list.length?`<div class="stack">${list.map(r=>`<div class="history-row"><div><strong>${r.status==='won'?'Victory':'Defeat'} · ${r.mode==='solo'?'Solo':'Coop'}</strong><div class="muted micro">${new Date(r.finishedAt).toLocaleString()} · Turn ${r.turn} · ${r.config.expansions.length?r.config.expansions.map(e=>EXP.find(x=>x[2]===e)?.[0]||e).join(', '):'Base game'}</div></div></div>`).join('')}</div>`:'<p>No completed games saved yet. Finish a game to see it here.</p>'}${list.length?btn('Clear completed history','historyClear','danger'):''}</section></div>`;}
function render(){const focused=document.activeElement;const focusKind=['action','pick','setting','expansion','difficulty'].find(k=>focused?.dataset?.[k]);const focusValue=focusKind?focused.dataset[focusKind]:null;page=location.hash||'#/';let content;
  if(page==='#/setup')content=setup();else if(page==='#/join')content=joinPage();else if(page==='#/rules')content=rules();else if(page==='#/roadmap')content=roadmap();else if(page==='#/multiplayer')content=multiplayer();else if(page==='#/settings')content=settings();else if(page==='#/history')content=historyPage();else if(page==='#/tutorial')content=tutorial();else if(page==='#/game')content=!state?'<div class="loading">Loading the dream…</div>':state.room.started?board(state.game,state.room):lobby(state.room);else content=home();
  app.innerHTML=nav()+`<main class="page" id="main-content" tabindex="-1">${error?`<div class="notice error" role="alert">${escape(error)} <button class="mini ghost" data-action="clearError">Dismiss</button></div>`:''}${content}</main>`+bottomNav();
  if(focusKind){const replacement=[...(app.querySelectorAll?.('[data-action],[data-pick],[data-setting],[data-expansion],[data-difficulty]')||[])].find(el=>el.dataset?.[focusKind]===focusValue);replacement?.focus?.({preventScroll:true});}
}
function pick(id){selected=selected===id?null:id;render();}
function moveProphecy(id,dir){let i=prophecyOrder.indexOf(id),j=i+dir;if(j<0||j>=prophecyOrder.length)return;[prophecyOrder[i],prophecyOrder[j]]=[prophecyOrder[j],prophecyOrder[i]];render();}
async function handle(actionName){
  if(actionName==='soloStart'){selectedMode='solo';return create('solo');}if(actionName==='coopStart'){selectedMode='coop';return create('coop');}
  if(actionName==='history')return setRoute('#/history');
  if(actionName==='tutorial'){tutorialStep=0;return setRoute('#/tutorial');}
  if(actionName==='tutorialBack'){tutorialStep=Math.max(0,tutorialStep-1);return render();}
  if(actionName==='tutorialNext'){tutorialStep=Math.min(TUTORIAL.length-1,tutorialStep+1);return render();}
  if(actionName==='tutorialStart'){selectedMode='solo';selectedExpansions.clear();selectedDifficulties={};return setRoute('#/setup');}
  if(actionName==='historyClear'){if(confirm('Delete all completed game summaries stored in this browser?')){clearHistory(localStorage);return render();}return;}
  if(actionName==='presetSave'){try{const preset=savePreset(localStorage,document.querySelector('#presetName')?.value,currentSetup());return render();}catch(e){return setError(e.message);}}
  if(actionName.startsWith('presetLoad:')){const preset=readPresets(localStorage).find(p=>p.id===actionName.slice(11));if(!preset)return setError('Saved setup not found');selectedExpansions=new Set(preset.config.expansions);selectedDifficulties={...preset.config.difficulties};return render();}
  if(actionName.startsWith('presetDelete:')){const id=actionName.slice(13);if(confirm('Delete this saved setup?')){deletePreset(localStorage,id);return render();}return;}
  if(actionName==='setup')return setRoute('#/setup');if(actionName==='roadmap')return setRoute('#/roadmap');if(actionName==='rules')return setRoute('#/rules');if(actionName==='joinPage')return setRoute('#/join');
  if(actionName==='solo'||actionName==='coop'){selectedMode=actionName;return setRoute('#/setup');}
  if(actionName==='chooseSolo'||actionName==='chooseCoop'){selectedMode=actionName==='chooseSolo'?'solo':'coop';return render();}
  if(actionName==='create')return create(selectedMode);if(actionName==='join')return join();
  if(actionName==='resume'){await refresh();setRoute('#/game');return startStream();}
  if(actionName==='ready')return doRoom('ready',{ready:!state.room.ready[session.seat]});
  if(actionName==='start')return doRoom('start');
  if(actionName==='copyCode'){await navigator.clipboard?.writeText(state.room.code);return;}
  if(actionName==='clearError'){error='';return render();}
  if(!state?.game)return;
  const g=state.game;if(state.room.seat!==g.active)return;
  if(g.phase==='draft'&&actionName.startsWith('draft:'))return action({type:'draft',id:actionName.slice(6)});
  if(actionName==='escape')return action({type:'escape'});
  if(actionName==='incubusActivate')return action({type:'incubusActivate'});
  if(actionName==='incubusCancel')return action({type:'incubusCancel'});
  if(actionName.startsWith('sphinxName:'))return action({type:'sphinxName',aspect:actionName.slice(11)});
  if(actionName==='sphinxConfirm')return action({type:'sphinxResolve',topId:effectPick,order:effectOrder});
  if(actionName==='diverContinue')return action({type:'diver',option:'continue'});
  if(actionName==='diverStop')return action({type:'diver',option:'stop',order:effectOrder.filter(id=>id!==g.pending.cards.at(-1).id)});
  if(actionName==='diverNightmare')return action({type:'diver',option:'nightmare',order:effectOrder});
  if(actionName==='confusionResolve'){const cards=[...g.players[g.active].hand,...(g.mode==='coop'?g.shared:[])];return action({type:'confusion',order:cards.map(c=>c.id)});}
  if(actionName.startsWith('mirrorPlay:')){const m=actionName.slice(11),cards=[...g.players[g.active].hand,...(g.mode==='coop'?g.shared:[])].filter(c=>c.kind==='location');if(cards.length<2)return setError('Need two Location cards.');const chosen=prompt('Enter two hand-card numbers separated by a comma: \n'+cards.map((c,i)=>`${i+1}. ${c.color} ${c.symbol}`).join('\n'),'1,2');if(chosen===null)return;const indices=chosen.split(',').map(x=>Number(x.trim())-1);if(indices.length!==2||indices.some(i=>!cards[i]))return setError('Choose two valid cards.');let freeId;
    if(m==='green'&&g.expansion?.mirrors?.stacks?.green?.length===2&&g.expansion?.dreamcatchers){
      const choices=g.expansion.dreamcatchers.stacks.map((cards,i)=>cards.length&&g.expansion.dreamcatchers.active[i]?i:null).filter(i=>i!==null);
      if(choices.length){const value=prompt(`Optional Dreamcatcher freeing during the Green Mirror search. Enter a catcher number (${choices.map(i=>i+1).join(', ')}) or leave blank:`, '');if(value===null)return; if(value.trim()!==''){freeId=Number(value)-1;if(!choices.includes(freeId))return setError('Choose an occupied Dreamcatcher number.');}}
    }
    return action({type:'mirrorPair',mirror:m,ids:indices.map(i=>cards[i].id),freeId});}
  if(actionName==='mirrorRewardConfirm'){const ids=[...mirrorSelection];mirrorSelection.clear();return action({type:'mirrorReward',ids,color:document.querySelector('#mirrorColor')?.value,freeId:searchFreeId()});}
  if(actionName.startsWith('mirror:'))return action({type:'nightmare',option:'mirror',denizenId:actionName.slice(7)});
  if(actionName.startsWith('happyBanish:'))return action({type:'happyDream',option:'banish',premonitionId:actionName.slice(12)});
  if(actionName==='happyPeek')return action({type:'happyDream',option:'peek'});
  if(actionName==='happyFetch')return action({type:'happyDream',option:'fetch'});
  if(actionName.startsWith('happyFetch:'))return action({type:'happyFetch',cardId:actionName.slice(11),freeId:searchFreeId()});
  if(actionName.startsWith('rally:'))return action({type:'rally',cardId:actionName.slice(6)});
  if(actionName.startsWith('premonitionPick:'))return action({type:'premonitionPick',id:actionName.slice(16)});
  if(actionName.startsWith('premonitionDoor:'))return action({type:'premonitionDoor',doorId:actionName.slice(16)});
  if(actionName.startsWith('effectDiscard:')){const id=actionName.slice(14);if(effectDiscards.has(id))effectDiscards.delete(id);else effectDiscards.add(id);return render();}
  if(actionName.startsWith('denizen:')){const id=actionName.slice(8),denizen=(g.expansion?.oniverse?.rallied||[]).find(d=>d.id===id);if(!denizen)return setError('Denizen unavailable');
    const ability=denizen.ability;if(['squirrel','harpoon','hammer'].includes(ability))return action({type:'useDenizen',id});
    const cards=[...g.players[g.active].hand,...(g.mode==='coop'?g.shared:[])];
    if(ability==='architect'||ability==='keeper'){
      const c=cards.find(x=>x.id===selected);if(!c)return setError('Select a Location from your hand or shared resources first.');return action({type:'useDenizen',id,cardId:c.id});
    }
    if(ability==='cyclobot'){
      const c=cards.find(x=>x.id===selected);if(!c)return setError('Select a hand Location to exchange first.');
      const discards=g.discard.filter(x=>x.kind==='location');if(!discards.length)return setError('There are no discarded Locations to exchange.');
      const choice=prompt('Choose a discarded Location by number:\n'+discards.map((x,i)=>`${i+1}. ${x.color} ${x.symbol}`).join('\n'),'1');
      if(choice===null)return;const chosen=discards[Number(choice)-1];if(!chosen)return setError('Invalid selection');return action({type:'useDenizen',id,cardId:c.id,discardId:chosen.id});
    }
  }
  if(actionName==='towerLeft'||actionName==='towerRight'){if(!selected)return setError('Choose a Tower.');return action({type:'playTower',id:selected,side:actionName==='towerLeft'?'left':'right'});}
  if(actionName==='play'||actionName==='discard'){
    if(!selected)return setError('Select a card first.');
    const c=[...g.players[g.active].hand,...(g.mode==='coop'?g.shared:[])].find(x=>x.id===selected);
    if(!c)return setError('Selected card is not available.');
    if(actionName==='play'&&g.players[g.active].labyrinth.at(-1)?.symbol===c.symbol)return setError('The next Location needs a different symbol.');
    const command={type:actionName,id:selected};
    if(actionName==='discard'&&g.mode==='coop'){
      const want=confirm('After discarding, swap one of your personal cards with one shared card? (Cancel = discard without swapping)');
      if(want){const personals=g.players[g.active].hand.filter(x=>x.id!==selected),shared=g.shared.filter(x=>x.id!==selected);
        if(personals.length&&shared.length){const personal=prompt('Personal card to swap (enter card number):\n'+personals.map((x,i)=>`${i+1}. ${x.color} ${x.symbol}`).join('\n'),'1');
          const sh=prompt('Shared card to swap (enter card number):\n'+shared.map((x,i)=>`${i+1}. ${x.color} ${x.symbol}`).join('\n'),'1');
          const p=personals[Number(personal)-1],q=shared[Number(sh)-1];if(!p||!q)return setError('Swap cancelled. Discard has not been submitted.');command.swapWith={personal:p.id,shared:q.id};
        }
      }
    }
    return action(command);
  }
  if(actionName.startsWith('doorSearch:')){const value=document.querySelector('#freeOnSearch')?.value,parts=actionName.split(':');return action({type:'doorSearch',option:parts[1],doorId:parts[2],freeId:value===''||value===undefined?undefined:Number(value)});}
  if(actionName.startsWith('useKey:'))return action({type:'chooseDoor',keyId:actionName.slice(7)});
  if(actionName.startsWith('nightKey:'))return action({type:'nightmare',option:'key',cardId:actionName.slice(9)});
  if(actionName.startsWith('nightDoor:'))return action({type:'nightmare',option:'door',cardId:actionName.slice(10)});
  if(actionName==='nightReveal')return action({type:'nightmare',option:'reveal'});
  if(actionName==='nightHand')return action({type:'nightmare',option:'hand'});
  if(actionName.startsWith('prophecyDiscard:')){prophecyDiscard=actionName.slice(16);return render();}
  if(actionName.startsWith('prophecyUp:'))return moveProphecy(actionName.slice(11),-1);
  if(actionName.startsWith('prophecyDown:'))return moveProphecy(actionName.slice(13),1);
  if(actionName.startsWith('freeCatcher:'))return action({type:'freeCatcher',index:Number(actionName.slice(12))});
  if(actionName.startsWith('catchChoose:'))return action({type:'catchChoose',index:Number(actionName.slice(12))});
  if(actionName.startsWith('catchOverload:'))return action({type:'catchOverload',index:Number(actionName.slice(14))});
  if(actionName.startsWith('towerPenalty:'))return action({type:'towerPenalty',option:'discard',towerId:actionName.slice(13)});
  if(actionName==='towerFake')return action({type:'towerPenalty',option:'fake'});
  if(actionName.startsWith('spellCost:')){const id=actionName.slice(10);if(spellSelected.has(id))spellSelected.delete(id);else spellSelected.add(id);return render();}
  if(actionName==='castSpell'){const goals=state.game.expansion?.book?.goals||[];const a=Number(document.querySelector('#goalA')?.value)-1,b=Number(document.querySelector('#goalB')?.value)-1;return action({type:'cast',spell:spellChoice,costIds:[...spellSelected],...(spellChoice==='parallel'?{first:a,second:b}:{})});}
  if(actionName.startsWith('effectPick:')){effectPick=actionName.slice(11);return render();}
  if(actionName.startsWith('effectUp:')||actionName.startsWith('effectDown:')){const id=actionName.split(':')[1],i=effectOrder.indexOf(id),j=i+(actionName.startsWith('effectUp:')?-1:1);if(i>=0&&j>=0&&j<effectOrder.length)[effectOrder[i],effectOrder[j]]=[effectOrder[j],effectOrder[i]];return render();}
  if(actionName==='effectConfirm'){const p=state.game.pending;const cards=p.cards;if(p.type==='happyPeek')return action({type:'happyPeek',discardIds:[...effectDiscards],order:effectOrder.filter(id=>!effectDiscards.has(id))});if(p.type==='denizenPeek')return action({type:'denizenPeek',order:effectOrder});return p.type==='towerLook'?action({type:'towerLook',order:effectOrder}):p.type==='spellPeek'?action({type:'spellPeek',topId:effectPick,bottomOrder:effectOrder.filter(id=>id!==effectPick)}):action({type:'incantation',doorId:effectPick||undefined,order:effectOrder.filter(id=>id!==effectPick)});}
  if(actionName==='prophecyConfirm'){if(!prophecyDiscard)return setError('Choose one card to discard.');return action({type:'prophecy',discardId:prophecyDiscard,order:prophecyOrder.filter(id=>id!==prophecyDiscard)});}
}
app.addEventListener('change',e=>{if(e.target?.dataset?.mirrorChoice){if(e.target.checked)mirrorSelection.add(e.target.dataset.mirrorChoice);else mirrorSelection.delete(e.target.dataset.mirrorChoice);return;}if(e.target?.dataset?.expansion){const id=e.target.dataset.expansion;if(e.target.checked){if(id==='incubus')selectedExpansions.clear();else selectedExpansions.delete('incubus');selectedExpansions.add(id);}else{selectedExpansions.delete(id);delete selectedDifficulties[id];}return render();}if(e.target?.dataset?.difficulty){selectedDifficulties[e.target.dataset.difficulty]=e.target.value;return render();}if(e.target?.dataset?.spellChoice){spellChoice=e.target.value;spellSelected.clear();return render();}const key=e.target?.dataset?.setting;if(!['theme','motion','cardSize','contrast','textSize'].includes(key))return;const value=e.target.value;if(key==='theme'&&!THEME_PRESETS.some(t=>t.id===value))return;if(key==='motion'&&!['normal','reduced'].includes(value))return;if(key==='cardSize'&&!['normal','large'].includes(value))return;if(key==='contrast'&&!['normal','high'].includes(value))return;if(key==='textSize'&&!['normal','large'].includes(value))return;uiSettings[key]=value;localStorage.setItem(SETTINGS_KEY,JSON.stringify(uiSettings));applySettings();render();});
app.addEventListener('click',e=>{
  const target=e.target.closest('[data-action],[data-pick]');if(!target)return;
  if(target.dataset.pick){if(state?.game?.phase==='draft')handle(`draft:${target.dataset.pick}`);else pick(target.dataset.pick);return;}
  handle(target.dataset.action);
});
addEventListener('hashchange',render);
render();if(STATIC_SITE){import('./engine/game.js').then(m=>{localEngine=m;return refresh();}).catch(e=>setError('Unable to load offline rules engine: '+e.message));}else if(session){refresh().then(()=>{if((location.hash||'#/')==='#/game')startStream();});}
